import tokens from "@/designs/tokens.json";

/**
 * Install (PWA) settings, used by app/manifest.ts and the root layout's viewport.
 * Colors come straight from designs/tokens.json, so app code holds no hex values.
 * theme = background (white): the status bar / title bar blends into the white
 * compact header.
 */
export const appColors = {
  theme: tokens.storefront.color.background.value,
  background: tokens.storefront.color.background.value,
} as const;

export const appName = "Ecomfy";

/** Generated by `pnpm icons` (scripts/app-icons.ts) into public/icons. */
export const appIcons = {
  any192: "/icons/icon-192.png",
  any512: "/icons/icon-512.png",
  maskable512: "/icons/maskable-512.png",
  apple: "/icons/apple-touch-icon.png",
} as const;
